sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  console.log("Before API : ", api);
  console.log("Before Helper : ", helpers);
  if (api.item.value.percentage > 80) {
    return 'optimal';
  } else if (api.item.value.percentage > 50) {
    return 'warning';
  } else {
    return 'critical';
  }
}
